\maketitle

\begin{abstract}
Brocard's problem asks for all natural numbers $n$ such that $n! + 1$ is a
perfect square. The only known solutions are the \emph{Brown numbers}
$n \in \{4, 5, 7\}$, giving $(n,m) = (4,5), (5,11), (7,71)$; whether these are
the only solutions is a famous open conjecture (Brocard 1876, Ramanujan 1913).
We recast the problem in the language of figurate (triangular) numbers. Writing
$T_y = y(y+1)/2$ for the $y$-th triangular number, we prove the unconditional
equivalence, for $n \ge 2$,
$\bigl(\exists\, y,\ n! = 8\,T_y\bigr) \iff \bigl(\exists\, m,\ n! + 1 = m^2\bigr)$,
i.e.\ $n!/8$ is triangular precisely when $n$ is a Brown number. The bridge is the
classical discriminant identity $8\,T_y + 1 = (2y+1)^2$, which we promote to a
full two-way square characterization of triangularity: $t$ is triangular iff
$8t + 1$ is a perfect square. As corollaries we obtain (i) the fact that any
Brown root $m$ is odd with index map $y \mapsto 2y+1$, (ii) the explicit
triangular indices $2, 5, 35$ of the three Brown numbers, and (iii) a finite,
exhaustive verification that no Brown number exists for $8 \le n \le 50$. We do
not claim the full classification --- that is exactly Brocard's open problem ---
but we make the geometric dictionary completely rigorous and discuss several
falsifiable research directions. All results have been formally verified.
\end{abstract}

\noindent\textbf{Keywords:} Brocard's problem, Brown numbers, triangular numbers,
figurate numbers, factorial, perfect square, discriminant identity, Wilson's
theorem.

\section{Introduction}

\subsection{Brocard's problem}
For a natural number $n$, the factorial is $n! = \prod_{k=1}^{n} k$ (with
$0! = 1! = 1$). \emph{Brocard's problem} asks: for which $n$ does there exist an
integer $m$ with $n! + 1 = m^2$? Direct computation finds
\[
4! + 1 = 25 = 5^2, \qquad 5! + 1 = 121 = 11^2, \qquad 7! + 1 = 5041 = 71^2,
\]
corresponding to $n = 4, 5, 7$, the \emph{Brown numbers}. Extensive computation
(to $n$ exceeding $10^9$) has revealed no further solutions, and it is conjectured
there are none. No proof is known. The problem was posed by Henri Brocard in 1876
and independently by Srinivasa Ramanujan in 1913.

\subsection{A geometric reformulation}
We study Brocard's problem through \emph{figurate numbers}, specifically the
triangular numbers $T_y = y(y+1)/2$ counting dots in a triangular array of side
$y$. Our central observation is that the classical identity
$8\,T_y + 1 = (2y+1)^2$, read in both directions, converts Brocard's problem into
a question purely about triangularity: for $n \ge 2$, the integer $n!/8$ is
triangular if and only if $n! + 1$ is a perfect square. This dictionary is exact
and unconditional. It does not resolve Brocard's problem --- the full
classification ``only $\{4,5,7\}$'' remains open --- but provides a clean
geometric face to every solution.

\subsection{Contributions}
\begin{enumerate}
\item A division-free characterization of triangular numbers and the discriminant
identity $8T_y + 1 = (2y+1)^2$ (Section~\ref{sec:disc}).
\item A two-way square characterization of triangularity: $t$ is triangular iff
$8t+1$ is a perfect square (Section~\ref{sec:char}).
\item The main geometric equivalence for Brocard's problem
(Section~\ref{sec:main}).
\item Structural corollaries: oddness of the Brown root and the index map
$y \mapsto 2y+1$; the explicit indices $2, 5, 35$ (Section~\ref{sec:cor}).
\item A finite exhaustive verification that no Brown number exists for
$8 \le n \le 50$ (Section~\ref{sec:finite}).
\item A discussion of falsifiable research directions
(Section~\ref{sec:future}).
\end{enumerate}

\section{Preliminaries and definitions}
We work in the natural numbers $\NN = \{0, 1, 2, \dots\}$.

\begin{definition}[Triangular number]
For $y \in \NN$, the $y$-th \emph{triangular number} is
$T_y := y(y+1)/2$. Since $y(y+1)$ is even, $T_y \in \NN$. The first values are
$T_0 = 0, T_1 = 1, T_2 = 3, T_3 = 6, T_4 = 10, T_5 = 15, \dots$
\end{definition}

\begin{definition}[Perfect square]
An integer $s$ is a \emph{perfect square} if $s = m^2$ for some $m \in \NN$.
\end{definition}

\begin{definition}[Brown number]
A natural number $n$ is a \emph{Brown number} if there exists $m \in \NN$ with
$n! + 1 = m^2$.
\end{definition}

\begin{definition}[Triangular witness]
Given $n$, a \emph{triangular witness} is an index $y$ with $n! = 8\,T_y$, i.e.\
$n!/8 = T_y$.
\end{definition}

\begin{remark}
We phrase ``triangular'' as the existence of an index, $\exists\, y,\ t = T_y$,
rather than a floor-division condition. This makes the characterizing equivalence
symmetric and avoids truncated natural-number division.
\end{remark}

\section{The discriminant identity}\label{sec:disc}

\begin{lemma}[Division-free triangular identity]\label{lem:divfree}
For all $y \in \NN$, $\ 2\,T_y = y(y+1)$.
\end{lemma}
\begin{proof}[Proof sketch]
By definition $T_y = y(y+1)/2$ with exact division because $2 \mid y(y+1)$
(consecutive integers). Multiplying back by $2$ cancels the division. The
divisibility must be discharged before algebraic normalization, since
natural-number division is otherwise opaque to such tactics.
\end{proof}

\begin{theorem}[Figurate discriminant identity]\label{thm:disc}
For all $y \in \NN$, $\ 8\,T_y + 1 = (2y + 1)^2$.
\end{theorem}
\begin{proof}[Proof sketch]
Expand $(2y+1)^2 = 4y^2 + 4y + 1 = 4\,y(y+1) + 1$. By
Lemma~\ref{lem:divfree}, $y(y+1) = 2T_y$, so $4\,y(y+1) = 8\,T_y$, giving
$(2y+1)^2 = 8\,T_y + 1$.
\end{proof}

\begin{remark}[Geometric reading]
Eight congruent triangular arrays of side $y$, together with one central dot,
tile exactly a square array of odd side $2y+1$. This is why ``multiply by $8$,
add $1$'' detects triangularity.
\end{remark}

\section{Square characterization of triangular numbers}\label{sec:char}

\begin{lemma}[Root parity]\label{lem:rootparity}
If $8t + 1 = m^2$, then $m$ is odd.
\end{lemma}
\begin{proof}[Proof sketch]
The left side $8t + 1$ is odd, so $m^2$ is odd, hence $m$ is odd.
\end{proof}

\begin{theorem}[Square characterization of triangularity]\label{thm:char}
For all $t \in \NN$,
\[
\bigl(\exists\, y,\ t = T_y\bigr) \iff \bigl(\exists\, m,\ 8t + 1 = m^2\bigr).
\]
\end{theorem}
\begin{proof}[Proof sketch]
($\Rightarrow$) If $t = T_y$, take $m = 2y + 1$; Theorem~\ref{thm:disc} gives
$8t + 1 = (2y+1)^2 = m^2$.
($\Leftarrow$) If $8t + 1 = m^2$, then $m$ is odd by
Lemma~\ref{lem:rootparity}, say $m = 2y + 1$. Then
$m^2 = (2y+1)^2 = 8T_y + 1$, and comparing with $m^2 = 8t + 1$ gives $t = T_y$,
with explicit index $y = (m-1)/2$.
\end{proof}

\begin{remark}
The equivalence is non-vacuous: both predicates hold for $t \in \{0,1,3,6,10\}$
and fail for $t \in \{2,4,5\}$.
\end{remark}

\section{The main geometric equivalence}\label{sec:main}

\begin{lemma}[Brown root is odd]\label{lem:brownodd}
Let $n \ge 2$ and suppose $n! + 1 = m^2$. Then $m$ is odd.
\end{lemma}
\begin{proof}[Proof sketch]
Since $n \ge 2$, $2 \mid n!$, so $n!$ is even and $m^2 = n! + 1$ is odd;
therefore $m$ is odd.
\end{proof}

\begin{theorem}[Main equivalence --- Brocard via triangular numbers]\label{thm:main}
For $n \ge 2$,
\[
\bigl(\exists\, y,\ n! = 8\,T_y\bigr) \iff \bigl(\exists\, m,\ n! + 1 = m^2\bigr).
\]
\end{theorem}
\begin{proof}[Proof sketch]
($\Rightarrow$) Given $y$ with $n! = 8T_y$, set $m = 2y + 1$; then
$n! + 1 = 8T_y + 1 = (2y+1)^2 = m^2$ by Theorem~\ref{thm:disc}.
($\Leftarrow$) Given $m$ with $n! + 1 = m^2$, Lemma~\ref{lem:brownodd} gives $m$
odd, say $m = 2y + 1$. By Theorem~\ref{thm:disc}, $m^2 = 8T_y + 1$, so
$n! = 8T_y$, with witness $y = (m-1)/2$.
\end{proof}

\begin{remark}
The Brown numbers are exactly the $n$ for which $n!/8$ is a perfect triangle of
dots. The equivalence is unconditional; it reformulates, but does not resolve,
the open classification.
\end{remark}

\section{Structural corollaries}\label{sec:cor}

\begin{corollary}[Index map]\label{cor:index}
In any Brown pair $(n, m)$ with $n \ge 2$, the root is odd and $m = 2y + 1$ where
$y = (m-1)/2$ is the triangular index:
\[
y \longmapsto m = 2y + 1, \qquad m \longmapsto y = \tfrac{m-1}{2}.
\]
\end{corollary}

\begin{theorem}[The three Brown numbers in triangular form]\label{thm:three}
\[
4! = 8\,T_2, \qquad 5! = 8\,T_5, \qquad 7! = 8\,T_{35}.
\]
\end{theorem}
\begin{proof}
$4! = 24 = 8\cdot 3 = 8T_2$; $5! = 120 = 8\cdot 15 = 8T_5$;
$7! = 5040 = 8\cdot 630 = 8T_{35}$.
\end{proof}

Via the index map the roots are $5, 11, 71$, recovering $(4,5), (5,11), (7,71)$.
The indices $2, 5, 35$ have gaps $3$ and $30$ with no apparent pattern.

\section{Finite verification}\label{sec:finite}

\begin{theorem}[No Brown number for $8 \le n \le 50$]\label{thm:finite}
For every $n$ with $8 \le n \le 50$ there is no $m$ with $n! + 1 = m^2$.
Equivalently, there is no triangular witness for $n!/8$ in this range.
\end{theorem}
\begin{proof}[Proof sketch]
Exhaustive case analysis over the finitely many $n$. For each $n$ one compares
$n! + 1$ with $\lfloor\sqrt{n!+1}\rfloor^2$ and observes they differ. The
computation is finite and decidable.
\end{proof}

\begin{remark}
Theorem~\ref{thm:finite} makes Theorem~\ref{thm:main} demonstrably non-vacuous:
both predicates have models ($n = 4,5,7$) and non-models ($n = 8,\dots,50$).
\end{remark}

\section{Discussion and future directions}\label{sec:future}

The reformulation gives Brocard's problem a figurate face, but deciding
triangularity of $n!/8$ uniformly in $n$ is equivalent to Brocard's open
classification. We record falsifiable directions.

\paragraph{C1. Linear-detector rigidity.} Conjecture: among positive integer
pairs $(a,b)$, $a\,t + b$ is a perfect square for every triangular $t$ and a
non-square for every non-triangular $t$ iff $(a,b) = (8,1)$. The $(8,1)$
direction is Theorem~\ref{thm:char}; uniqueness is checkable by finite search.

\paragraph{C2. Density and the factor-split obstruction.} Conjecture:
$\{n : n!/8 \text{ triangular}\}$ has density $0$, and $n! + 1$ is never square for
$n \ge 8$. Here $n! + 1 = m^2$ forces $(m-1)(m+1) = n!$ with
$\gcd(m-1, m+1) \le 2$, splitting $n!$ into two near-equal almost-coprime
factors --- increasingly implausible as the prime content of $n!$ grows.

\paragraph{C3. Wilson-index obstruction.} Conjecture: if $n = p - 1$ for a prime
$p \ge 11$, then $n!/8$ is not triangular. By Wilson's theorem
$(p-1)! \equiv -1 \pmod p$, so $p \mid m^2$, forcing $m \ge p$ and $m^2 \ge p^2$;
comparing with $m^2 = (p-1)! + 1$ and $(p-1)! \ge p^2$ contradicts for large $p$.

\paragraph{C4. Triangular-index growth law.} The indices $2, 5, 35$ are
conjecturally the only $y$ with $8T_y + 1 = n! + 1$, obeying no polynomial
recurrence (gaps $3, 30$). The index map $y = (\sqrt{n!+1} - 1)/2$ inherits the
irregularity of $n!$.

\section{Conclusion}
The classical identity $8T_y + 1 = (2y+1)^2$, read in both directions, yields a
square characterization of triangularity (Theorem~\ref{thm:char}) and, for
factorial-eighths, the unconditional equivalence ``$n!/8$ triangular $\iff$
$n!+1$ square'' (Theorem~\ref{thm:main}). The three Brown numbers become explicit
triangles of sides $2, 5, 35$, the root is always $m = 2y + 1$, and no new
solution exists for $8 \le n \le 50$. The full classification remains the open
Brocard--Ramanujan conjecture, but the figurate dictionary clarifies what a
fourth solution would look like.

